//! Loading of wordlists and other line based files.

use std::collections::BTreeSet;
use std::fs;
use std::sync::Arc;

use crate::arg_parse::GlobalOpts;

/// Decode the raw bytes of a file into a String. UTF-8 is used when the
/// contents are valid UTF-8, otherwise the file is treated as windows-1252.
fn decode_bytes(bytes: &[u8]) -> String {
    match String::from_utf8(bytes.to_vec()) {
        Ok(s) => s,
        Err(_) => {
            let mut out = String::with_capacity(bytes.len());
            for &b in bytes {
                out.push(cp1252_char(b));
            }
            out
        }
    }
}

fn cp1252_char(b: u8) -> char {
    const HIGH: [u32; 32] = [
        0x20AC, 0x0081, 0x201A, 0x0192, 0x201E, 0x2026, 0x2020, 0x2021, 0x02C6, 0x2030, 0x0160,
        0x2039, 0x0152, 0x008D, 0x017D, 0x008F, 0x0090, 0x2018, 0x2019, 0x201C, 0x201D, 0x2022,
        0x2013, 0x2014, 0x02DC, 0x2122, 0x0161, 0x203A, 0x0153, 0x009D, 0x017E, 0x0178,
    ];
    if (0x80..0xA0).contains(&b) {
        char::from_u32(HIGH[(b - 0x80) as usize]).unwrap_or('\u{FFFD}')
    } else {
        b as char
    }
}

/// Read a file and return its lines. Mirrors the failure behaviour of the
/// original tool: a missing file or an empty file aborts the program.
pub fn lines_of_file_at(filename: &str, location_prefix: &str) -> Vec<String> {
    let bytes = match fs::read(filename) {
        Ok(b) => b,
        Err(e) => {
            let kind = match e.kind() {
                std::io::ErrorKind::NotFound => "NotFound",
                std::io::ErrorKind::PermissionDenied => "PermissionDenied",
                std::io::ErrorKind::IsADirectory => "IsADirectory",
                _ => "Other",
            };
            let code = e.raw_os_error().unwrap_or(0);
            let message = match e.raw_os_error() {
                Some(c) => os_error_message(c),
                None => e.to_string(),
            };
            crate::panic_exit(
                &format!("{}src/wordlist.rs:112:37", location_prefix),
                &format!(
                    "called `Result::unwrap()` on an `Err` value: Os {{ code: {}, kind: {}, message: \"{}\" }}",
                    code, kind, message
                ),
            );
        }
    };
    if bytes.is_empty() {
        crate::panic_exit(
            &format!("{}src/wordlist.rs:130:13", location_prefix),
            &format!(
                "Error detecting file encoding of {} - is the file empty?",
                filename
            ),
        );
    }
    let contents = decode_bytes(&bytes);
    contents.lines().map(|l| l.to_string()).collect()
}

pub fn lines_of_file(filename: &str) -> Vec<String> {
    lines_of_file_at(filename, "")
}

fn os_error_message(code: i32) -> String {
    unsafe {
        let ptr = libc::strerror(code);
        if ptr.is_null() {
            return String::from("Unknown error");
        }
        std::ffi::CStr::from_ptr(ptr).to_string_lossy().into_owned()
    }
}

/// Strip a single leading and a single trailing slash from a word
fn clean_word(word: &str) -> String {
    let w = word.strip_prefix('/').unwrap_or(word);
    let w = w.strip_suffix('/').unwrap_or(w);
    w.to_string()
}

/// Load, deduplicate and sort all of the configured wordlists
pub fn load_wordlists(opts: &Arc<GlobalOpts>) -> Vec<String> {
    let mut words: BTreeSet<String> = BTreeSet::new();
    for file in &opts.wordlist_files {
        for line in lines_of_file(file) {
            words.insert(clean_word(&line));
        }
    }
    words.into_iter().collect()
}

/// Locate the default wordlist, which lives next to the executable
pub fn default_wordlist_path() -> Option<String> {
    let exe = std::env::current_exe().ok()?;
    let dir = exe.parent()?;
    let candidate = dir.join("dirble_wordlist.txt");
    if candidate.is_file() {
        Some(candidate.to_string_lossy().into_owned())
    } else {
        None
    }
}
