    pub fn curl_slist_append(list: *mut curl_slist, string: *const c_char) -> *mut curl_slist;
    pub fn curl_slist_free_all(list: *mut curl_slist);
}

/// Error information from a failed transfer
#[derive(Debug, Clone)]
pub struct CurlError {
    pub code: c_int,
    pub description: String,
    pub extra: Option<String>,
}

impl std::fmt::Display for CurlError {
    fn fmt(&self, f: &mut std::fmt::Formatter<'_>) -> std::fmt::Result {
        write!(f, "[{}] {}", self.code, self.description)?;
        if let Some(extra) = &self.extra {
            write!(f, " ({})", extra)?;
        }
        Ok(())
    }
}

/// Safe-ish wrapper around a libcurl easy handle
pub struct Easy {
    handle: *mut CURL,
    headers: *mut curl_slist,
    error_buf: Box<[u8; CURL_ERROR_SIZE]>,
    body: Box<Vec<u8>>,
    // Strings must outlive the transfer, keep them owned here
    owned: Vec<CString>,
}

unsafe impl Send for Easy {}

extern "C" fn write_callback(
    ptr: *const c_char,
    size: usize,
    nmemb: usize,
    userdata: *mut c_void,
) -> usize {
    let total = size * nmemb;
    if total == 0 {
        return 0;
    }
    unsafe {
        let body = &mut *(userdata as *mut Vec<u8>);
        let slice = std::slice::from_raw_parts(ptr as *const u8, total);
        body.extend_from_slice(slice);
    }
    total
}

extern "C" fn read_callback(
    _ptr: *mut c_char,
    _size: usize,
    _nmemb: usize,
    _userdata: *mut c_void,
) -> usize {
    0
}

pub fn global_init() {
    static INIT: std::sync::Once = std::sync::Once::new();
    INIT.call_once(|| unsafe {
        curl_global_init(CURL_GLOBAL_ALL);
    });
}

impl Easy {
    pub fn new() -> Easy {
        global_init();
        let handle = unsafe { curl_easy_init() };
        assert!(!handle.is_null(), "failed to initialise curl handle");
        let mut easy = Easy {
            handle,
            headers: std::ptr::null_mut(),
            error_buf: Box::new([0u8; CURL_ERROR_SIZE]),
            body: Box::new(Vec::new()),
            owned: Vec::new(),
        };
        easy.install_callbacks();
        easy
    }

    fn install_callbacks(&mut self) {
        unsafe {
            curl_easy_setopt(self.handle, CURLOPT_NOSIGNAL, 1 as c_long);
            curl_easy_setopt(self.handle, CURLOPT_NOPROGRESS, 1 as c_long);
            curl_easy_setopt(
                self.handle,
                CURLOPT_ERRORBUFFER,
                self.error_buf.as_mut_ptr() as *mut c_char,
            );
            curl_easy_setopt(
                self.handle,
                CURLOPT_WRITEFUNCTION,
                write_callback as extern "C" fn(*const c_char, usize, usize, *mut c_void) -> usize,
            );
            curl_easy_setopt(
                self.handle,
                CURLOPT_WRITEDATA,
                &mut *self.body as *mut Vec<u8> as *mut c_void,
            );
            curl_easy_setopt(
                self.handle,
                CURLOPT_READFUNCTION,
                read_callback as extern "C" fn(*mut c_char, usize, usize, *mut c_void) -> usize,
            );
        }
    }

    pub fn set_long(&mut self, option: CURLoption, value: c_long) {
        unsafe {
            curl_easy_setopt(self.handle, option, value);
        }
    }

    pub fn set_str(&mut self, option: CURLoption, value: &str) {
        let c = CString::new(value.replace('\0', "")).unwrap();
        unsafe {
            curl_easy_setopt(self.handle, option, c.as_ptr());
        }
        self.owned.push(c);
    }

    pub fn set_headers(&mut self, headers: &[String]) {
        unsafe {
            if !self.headers.is_null() {
                curl_slist_free_all(self.headers);
                self.headers = std::ptr::null_mut();
            }
            for h in headers {
                let c = CString::new(h.replace('\0', "")).unwrap();
                self.headers = curl_slist_append(self.headers, c.as_ptr());
            }
            if !self.headers.is_null() {
                curl_easy_setopt(self.handle, CURLOPT_HTTPHEADER, self.headers);
            }
        }
    }

    pub fn set_url(&mut self, url: &str) {
        self.set_str(CURLOPT_URL, url);
    }

    /// Perform the transfer, returning the body or the error
    pub fn perform(&mut self) -> Result<(), CurlError> {
        self.body.clear();
        self.error_buf[0] = 0;
        let code = unsafe { curl_easy_perform(self.handle) };
        if code == 0 {
            Ok(())
        } else {
            let description = unsafe {
                CStr::from_ptr(curl_easy_strerror(code))
                    .to_string_lossy()
                    .into_owned()
            };
            let extra_raw = unsafe { CStr::from_ptr(self.error_buf.as_ptr() as *const c_char) }
                .to_string_lossy()
                .into_owned();
            let extra = if extra_raw.is_empty() {
                None
            } else {
                Some(extra_raw)
            };
            Err(CurlError {
                code,
                description,
                extra,
            })
        }
    }

    pub fn body(&self) -> &[u8] {
        &self.body
    }

    pub fn response_code(&self) -> u32 {
        let mut code: c_long = 0;
        unsafe {
            curl_easy_getinfo(self.handle, CURLINFO_RESPONSE_CODE, &mut code as *mut c_long);
        }
        code as u32
    }

    pub fn redirect_url(&self) -> Option<String> {
        let mut ptr: *const c_char = std::ptr::null();
        unsafe {
            curl_easy_getinfo(
                self.handle,
                CURLINFO_REDIRECT_URL,
                &mut ptr as *mut *const c_char,
            );
            if ptr.is_null() {
                None
            } else {
                Some(CStr::from_ptr(ptr).to_string_lossy().into_owned())
            }
        }
    }
}

impl Drop for Easy {
    fn drop(&mut self) {
        unsafe {
            curl_easy_cleanup(self.handle);
            if !self.headers.is_null() {
                curl_slist_free_all(self.headers);
            }
        }
    }
}
