        easy.set_headers(&opts.headers);
    }
    if let (Some(user), Some(pass)) = (&opts.username, &opts.password) {
        easy.set_str(curl_ffi::CURLOPT_USERNAME, user);
        easy.set_str(curl_ffi::CURLOPT_PASSWORD, pass);
    }
    if opts.proxy_enabled {
        easy.set_str(curl_ffi::CURLOPT_PROXY, &opts.proxy_address);
    }
    if opts.ignore_cert {
        easy.set_long(curl_ffi::CURLOPT_SSL_VERIFYPEER, 0);
        easy.set_long(curl_ffi::CURLOPT_SSL_VERIFYHOST, 0);
    }
    easy
