    easy.set_url(url);
    let mut response = RequestResponse {
        url: url.to_string(),
        ..Default::default()
    };
    match easy.perform() {
        Ok(()) => {
            response.code = easy.response_code();
            response.content_len = easy.body().len();
            if response.code == 301 || response.code == 302 {
                match easy.redirect_url() {
                    Some(r) => {
                        if r == format!("{}/", url) {
                            response.is_directory = true;
                        }
                        response.redirect_url = r;
                    }
                    None => {
                        // The original tool unwraps the redirect destination and
                        // panics when it is missing.
                        crate::panic_thread(
                            "src/request.rs:161:55",
                            "called `Option::unwrap()` on a `None` value",
