                }
            }
        }
        Err(e) => {
            println!("Curl error after requesting {} : {}", url, e);
            response.code = 0;
        }
    }
    response
}

/// Check whether a response body indicates a directory listing
pub fn is_listable_body(body: &[u8]) -> bool {
    let lower = String::from_utf8_lossy(body).to_lowercase();
    lower.contains("parent directory")
        || lower.contains("directory listing for")
        || lower.contains("up to higher level directory")
}
