//! A small logger mimicking the terminal output format used by the tool:
//! INFO and WARN messages are prefixed by their level only, DEBUG messages
//! carry a timestamp, thread number and target and TRACE messages also
//! include the source location.

use std::io::Write;
use std::sync::atomic::{AtomicU8, Ordering};

pub const LEVEL_ERROR: u8 = 1;
pub const LEVEL_WARN: u8 = 2;
pub const LEVEL_INFO: u8 = 3;
pub const LEVEL_DEBUG: u8 = 4;
pub const LEVEL_TRACE: u8 = 5;

static MAX_LEVEL: AtomicU8 = AtomicU8::new(LEVEL_INFO);

pub fn set_max_level(level: u8) {
    MAX_LEVEL.store(level, Ordering::SeqCst);
}

pub fn max_level() -> u8 {
    MAX_LEVEL.load(Ordering::SeqCst)
}

pub fn enabled(level: u8) -> bool {
    level <= max_level()
}

/// Number of the current thread, matching the numbering used by the
/// standard library's ThreadId (the main thread is 1).
pub fn thread_number() -> u64 {
    let id = format!("{:?}", std::thread::current().id());
    let digits: String = id.chars().filter(|c| c.is_ascii_digit()).collect();
    digits.parse().unwrap_or(0)
}

fn timestamp() -> String {
    unsafe {
        let now = libc::time(std::ptr::null_mut());
        let mut tm: libc::tm = std::mem::zeroed();
        libc::localtime_r(&now, &mut tm);
        format!("{:02}:{:02}:{:02}", tm.tm_hour, tm.tm_min, tm.tm_sec)
    }
}

pub fn error(message: &str) {
    if enabled(LEVEL_ERROR) {
        let stderr = std::io::stderr();
        let mut lock = stderr.lock();
        let _ = writeln!(lock, "[ERROR] {}", message);
    }
}

pub fn warn(message: &str) {
    if enabled(LEVEL_WARN) {
        let stdout = std::io::stdout();
        let mut lock = stdout.lock();
        let _ = writeln!(lock, "[WARN] {}", message);
    }
}

pub fn info(message: &str) {
    if enabled(LEVEL_INFO) {
        let stdout = std::io::stdout();
        let mut lock = stdout.lock();
        let _ = writeln!(lock, "[INFO] {}", message);
    }
}

pub fn debug(target: &str, message: &str) {
    if enabled(LEVEL_DEBUG) {
        let stdout = std::io::stdout();
        let mut lock = stdout.lock();
        let _ = writeln!(
            lock,
            "{} [DEBUG] ({}) {}: {}",
            timestamp(),
            thread_number(),
            target,
            message
        );
    }
}

pub fn trace(target: &str, location: &str, message: &str) {
    if enabled(LEVEL_TRACE) {
        let stdout = std::io::stdout();
        let mut lock = stdout.lock();
        let _ = writeln!(
            lock,
            "{} [TRACE] ({}) {}: [{}] {}",
            timestamp(),
            thread_number(),
            target,
            location,
            message
        );
    }
}
